import inventoryFeatureImg from '../../../media/smartTransformer/image (3).png';

const TransformerMeasure = () => {
  const data = [
    {
      id: 1,
      list: 'Current',
    },
    {
      id: 2,
      list: 'Voltage',
    },
    {
      id: 3,
      list: 'Frequency',
    },
    {
      id: 4,
      list: 'Power Factor',
    },
    {
      id: 5,
      list: 'Active Energy',
    },
    {
      id: 6,
      list: 'Reactive Energy',
    },
    {
      id: 7,
      list: 'Apparent Energy',
    },
  ];
  return (
    <div
      className='inventory-feature'
      style={{ padding: '80px 0px' }}
    >
      <div className='container-fluid'>
        <div className='row d-flex justify-content-around align-items-center px-5'>
          <div
            className='col-md-5'
            data-aos='fade-right'
            data-aos-offset='300'
            data-aos-easing='ease-in-sine'
          >
            <h1 style={{ fontSize: '28px', fontWeight: '500' }}>
              Transformer Details Status
            </h1>
            <img
              className=' '
              src={inventoryFeatureImg}
              alt='interconnect billing'
              style={{ width: '100%', objectFit: 'contain' }}
            />
          </div>

          <div
            className='col-md-5'
            data-aos='fade-left'
            data-aos-offset='300'
            data-aos-easing='ease-in-sine'
          >
            <h1 style={{ fontSize: '28px', fontWeight: '500' }}>
              Measure Items(Phase & Line Parameter)
            </h1>
            {data.map((item, index) => {
              return (
                <li
                  className='pt-3'
                  style={{
                    fontSize: '15px',
                    textAlign: 'left',
                    paddingLeft: '20px',
                  }}
                  key={index}
                >
                  {item?.list}
                </li>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransformerMeasure;
